{
  "opening": "This release introduces significant enhancements to the VersionInfo class, including immutability enforcement, iteration support, and new methods for version manipulation. It also adds a command-line interface and a replace function for easier version string handling.",
  "requirements": [
    {
      "id": "m04",
      "text": "Attempting to assign a value to any of the major, minor, patch, prerelease, or build attributes on a VersionInfo instance must raise an AttributeError with a descriptive message."
    },
    {
      "id": "m07",
      "text": "A VersionInfo instance must be iterable, yielding its components in a defined order when used in iteration contexts such as loops or unpacking."
    },
    {
      "id": "m11",
      "text": "Comparisons between VersionInfo instances and tuples must be supported, while comparisons with strings or integers must be disallowed to prevent ambiguous type coercion."
    },
    {
      "id": "m13",
      "text": "The VersionInfo class must provide bump_major, bump_minor, bump_patch, bump_prerelease, and bump_build methods that return a new VersionInfo instance with the corresponding component incremented."
    },
    {
      "id": "m20",
      "text": "When creating a VersionInfo instance, prerelease and build arguments are automatically converted to strings, ensuring consistent type handling during comparison operations."
    },
    {
      "id": "m30",
      "text": "The library exposes a command-line entry point that accepts parsed arguments via createparser, processes them through process, and executes logic via main, enabling direct script usage."
    },
    {
      "id": "m31",
      "text": "The semver.replace function accepts a version string and keyword arguments to return a new formatted version string, while VersionInfo.replace returns a new VersionInfo instance with specified parts updated."
    }
  ],
  "closing": "Please ensure all public API behaviors described above are verified before tagging this release."
}
